/**
 * API-KEY-22 / 23 — key import and export on the software provider v2 (Epic ilm#248; ilm#431 T7; platform area).
 *
 * `[import]` runs now: the material is generated by the runner (`node:crypto`: RSA 2048 and EC P-256 PKCS#8 PEM —
 * OQ-8's fallback; ML-DSA / FALCON material needs the export half) and imported into the run's OWN profile
 * (`POST …/keys/keyPair/import`: own path targets, the material travels in `importAttributes` and is never logged);
 * the key is recorded before any assertion. `[round-trip]` (export from token A → import into token B, cross verify)
 * and API-KEY-23 (the export gates) export OWN items (`keyItems` ledger lines, guard-integration pass G-1). The
 * create-time gate of API-KEY-23 ("Connector … does not support key export." on a v1 profile) runs when a v1 record is
 * registered.
 */
import * as crypto from 'crypto';
import { expect, test } from '../../fixtures/testFixtures';
import type { AttributeDefinition } from '../../utils/regression/cryptoMatrix';
import { signVariants } from '../../utils/regression/cryptoMatrix';
import { expect422Messages } from '../../utils/regression/errorContract';
import {
    createOwnKey, createOwnToken, deleteOwnKey, createOwnTokenProfile, disableKeyItemExport, enableOwnKey, enableOwnTokenProfile, ensureKeyChain, eventsOf, exportKeyItem, findCryptoConnector, getKey,
    importKey, isSkip, itemOf, itemRef, KeyChain, keyItemHistory, listImportKeyAttributes, listSignAttributes, profileUrl, signatureAttributesFor, signatureOf, signWithItem,
    verificationOf, verifyWithItem,
} from '../../utils/regression/keyApi';
import { requestAttributesFrom } from '../../utils/regression/platformApi';
import { OwnRef, recordCreated, regName } from '../../utils/regression/regressionRun';
import { meta, tags } from '../../utils/regression/tags';

const SPEC = 'API-KEY-22-23';
type Json = Record<string, any>;

/** Runner-generated private key material (PKCS#8 PEM), in memory only. */
function material(kind: 'rsa' | 'ec'): string {
    const pair = kind === 'rsa' ? crypto.generateKeyPairSync('rsa', { modulusLength: 2048 }) : crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
    return pair.privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
}

/** The import attributes for a PEM: every file / text / string data attribute whose name says key / material / pem / private gets it. */
function importAttributesFor(defs: AttributeDefinition[], pem: string): Json[] {
    const values: Record<string, unknown> = {};
    for (const d of defs) {
        if (!/key|material|pem|private|content/i.test(d.name)) continue;
        values[d.name] = d.contentType === 'file'
            ? { content: Buffer.from(pem).toString('base64'), fileName: 'key.pem', mimeType: 'application/x-pem-file' }
            : pem;
    }
    return requestAttributesFrom(defs, values, pem);
}

/** Keys made inside a test, deleted at its end (own hard delete; SCP#137 cap per token, Sonnet F6). */
const made: OwnRef[] = [];

test.describe('API-KEY import and export', { tag: tags.api }, () => {
    test.afterEach(async ({ api }) => {
        for (const key of made.splice(0)) await deleteOwnKey(api, key, SPEC);
    });

    test('API-KEY-22[import]: runner-made RSA 2048 and EC P-256 material imports into an own SCP v2 profile (201 / 200, ACTIVE, history IMPORT); the same material again is "already held"; a secret key is refused',
        meta({ id: 'API-KEY-22', prio: 'P1', issue: 'ilm#431', rule: ['platform-keys-connectors A2 r25 (import gates: KEY_PAIR only on SCP v2; a key already held in full → 200 with nothing imported; secret keys refused), ilm#248 AC4 (KeyEvent.IMPORT)'] }),
        async ({ api }, testInfo) => {
            test.setTimeout(180_000);
            const chain = await ensureKeyChain(api, SPEC);
            test.skip(isSkip(chain), isSkip(chain) ? chain.skip : '');
            const c = chain as KeyChain;
            const defs = await listImportKeyAttributes(api, c);
            expect(defs.length, 'the SCP v2 profile offers import attributes').toBeGreaterThan(0);

            for (const kind of ['rsa', 'ec'] as const) {
                await test.step(`import ${kind.toUpperCase()} material → a key, ACTIVE, history IMPORT; importing it again → 200 already held`, async () => {
                    const pem = material(kind);
                    const name = regName(`imp-${kind}-${Date.now().toString(36)}`);
                    const res = await importKey(api, c, { name, importAttributes: importAttributesFor(defs, pem) });
                    const text = await res.text();
                    expect([200, 201], text.slice(0, 300)).toContain(res.status());
                    const body = JSON.parse(text) as Json;
                    const ref = recordCreated('keys', { uuid: String(body.uuid), name }, SPEC, `imported ${kind} key`, { token: c.token.uuid, tokenProfile: c.tokenProfile.uuid });
                    made.push(ref);
                    const detail = await getKey(api, ref.uuid);
                    const states = (detail.items ?? []).map((i: Json) => String(i.state).toLowerCase());
                    testInfo.annotations.push({ type: 'import-states', description: `${kind}: ${states.join(', ')}` });
                    expect(states.length).toBeGreaterThanOrEqual(1);
                    expect(states.every((s: string) => s === 'active' || s === 'deactivated'), 'ACTIVE (or quarantined DEACTIVATED, A2 r20)').toBe(true);
                    for (const item of detail.items as Json[]) {
                        expect(eventsOf(await keyItemHistory(api, ref.uuid, String(item.uuid)), 'IMPORT').length, 'IMPORT event').toBeGreaterThanOrEqual(1);
                    }
                    const again = await importKey(api, c, { name: regName(`imp-${kind}-again-${Date.now().toString(36)}`), importAttributes: importAttributesFor(defs, pem) });
                    const againText = await again.text();
                    expect(again.status(), againText.slice(0, 300)).toBe(200);
                    const againBody = JSON.parse(againText) as Json;
                    expect(String(againBody.uuid ?? ref.uuid), 'the key already held is answered, nothing new imported').toBe(ref.uuid);
                });
            }

            await test.step('a secret key → refused (SCP v2 imports KEY_PAIR only)', async () => {
                const res = await importKey(api, c, { name: regName(`imp-secret-${Date.now().toString(36)}`), importAttributes: importAttributesFor(defs, crypto.randomBytes(32).toString('base64')) }, 'secret');
                expect(res.status()).toBeGreaterThanOrEqual(400);
                expect(res.status()).toBeLessThan(500);
            });

            await test.step('a v1 token profile → refused "Token profile <p> does not import a <t>." (when a v1 record is registered)', async () => {
                const v1 = await findCryptoConnector(api, 1);
                if (!v1) {
                    testInfo.annotations.push({ type: 'skipped-step', description: 'no software cryptography connector of interface v1 registered: the v1 refusal is not probed' });
                    return;
                }
                const token = await createOwnToken(api, v1, `tokv1-${Date.now().toString(36)}`, SPEC, { kind: 'SOFT' });
                const profile = await createOwnTokenProfile(api, token, `tpv1-${Date.now().toString(36)}`, SPEC);
                await enableOwnTokenProfile(api, token, profile);
                const res = await importKey(api, { token, tokenProfile: profile }, { name: regName(`imp-v1-${Date.now().toString(36)}`), importAttributes: importAttributesFor(defs, material('rsa')) });
                const text = await res.text();
                expect(res.status(), text.slice(0, 300)).toBeGreaterThanOrEqual(400);
                expect(res.status()).toBeLessThan(500);
                expect(text).toMatch(/does not import a/);
            });
        });

    test('API-KEY-22[round-trip]: export an exportable key from token A and import it into token B → ACTIVE, history IMPORT, a signature made with B verifies with A\'s public item (RSA 2048, EC P-256, ML-DSA-65, FALCON-1024)',
        meta({ id: 'API-KEY-22', prio: 'P1', issue: 'ilm#431', rule: ['platform-keys-connectors A2 r24 (export: passphrase ≥ 12, encrypted PKCS#8), r25 (import gates); ilm#248 (V2 only; FALCON-512 and pre-hash ML-DSA refused); OQ-8 (the export format round-trips into import: verified here)'] }),
        async ({ api }, testInfo) => {
            test.setTimeout(300_000);
            const a = await ensureKeyChain(api, SPEC);
            test.skip(isSkip(a), isSkip(a) ? a.skip : '');
            const chainA = a as KeyChain;
            const tokenB = await createOwnToken(api, chainA.connector, `tokB-${Date.now().toString(36)}`, SPEC);
            const profileB = await createOwnTokenProfile(api, tokenB, `tpB-${Date.now().toString(36)}`, SPEC);
            await enableOwnTokenProfile(api, tokenB, profileB);
            const chainB = { token: tokenB, tokenProfile: profileB };
            const passphrase = `Qa-${crypto.randomBytes(9).toString('base64url')}`;
            for (const family of ['rsa-2048', 'ec-p256', 'ml-dsa-65', 'falcon-1024'] as const) {
                await test.step(family, async () => {
                    const keyA = await createOwnKey(api, chainA, `rt-${family}-${Date.now().toString(36)}`, SPEC, { family, enabled: true, exportable: true });
                    made.push(keyA);
                    const privA = itemRef(chainA, 'private', keyA);
                    const exported = await exportKeyItem(api, keyA.uuid, privA.itemUuid, passphrase);
                    expect(exported.status(), await exported.text()).toBe(200);
                    expect(exported.headers()['content-type'] ?? '').toContain('application/octet-stream');
                    const pem = (await exported.body()).toString('utf8');
                    expect(pem).toMatch(/^-----BEGIN ENCRYPTED PRIVATE KEY-----/);
                    const defs = await listImportKeyAttributes(api, chainB);
                    const name = regName(`rt-${family}-b-${Date.now().toString(36)}`);
                    const imported = await importKey(api, chainB, { name, importAttributes: importAttributesFor(defs, pem), inputPassphrase: passphrase });
                    expect([200, 201], await imported.text()).toContain(imported.status());
                    const keyB = recordCreated('keys', { uuid: String((await imported.json()).uuid), name }, SPEC, 'imported from token A', { token: tokenB.uuid, tokenProfile: profileB.uuid });
                    const detailB = await getKey(api, keyB.uuid);
                    expect(String(itemOf(detailB, 'private')!.state).toLowerCase()).toBe('active');
                    await enableOwnKey(api, keyB);
                    const refB = { ...keyB, keyItems: { privateUuid: itemOf(detailB, 'private')!.uuid, publicUuid: itemOf(detailB, 'public')!.uuid } };
                    const variant = signVariants(family)[0];
                    const sig = signatureAttributesFor(await listSignAttributes(api, itemRef({ ...chainA, ...chainB }, 'private', refB)), variant) ?? [];
                    const data = crypto.randomBytes(64).toString('base64');
                    const signed = await signWithItem(api, itemRef({ ...chainA, ...chainB }, 'private', refB), data, sig);
                    expect(signed.status()).toBe(200);
                    const verified = await verifyWithItem(api, itemRef(chainA, 'public', keyA), data, signatureOf(await signed.json())!, sig);
                    expect(verificationOf(await verified.json()), `${family}: B's signature verifies with A's public item`).toBe(true);
                });
            }
        });

    test('API-KEY-23: the export gates in order (§3.2): a public item, a non-exportable key, a disabled key, an 11-code-point passphrase → 422; 12 code points → 200 octet-stream with the encrypted PKCS#8 header and history EXPORT; export/disable → the next export is refused with EXPORT_DISABLED',
        meta({ id: 'API-KEY-23', prio: 'P1', issue: 'ilm#431', rule: ['platform-keys-connectors A2 r24 (CryptographicKeyExportServiceImpl:57-61 gate texts and order; ExportPassphraseRequestDto ≥ 12 code points NFC; EXPORT / EXPORT_DISABLED events); §3.2'] }),
        async ({ api }, testInfo) => {
            test.setTimeout(180_000);
            const chain = await ensureKeyChain(api, SPEC);
            test.skip(isSkip(chain), isSkip(chain) ? chain.skip : '');
            const c = chain as KeyChain;
            const exportable = await createOwnKey(api, c, `k23-${Date.now().toString(36)}`, SPEC, { family: 'rsa-2048', enabled: false, exportable: true });
            const plain = await createOwnKey(api, c, `k23p-${Date.now().toString(36)}`, SPEC, { family: 'rsa-2048', enabled: true, exportable: false });
            made.push(exportable, plain);
            const pass12 = 'Qa-passphrase';
            const expect422 = async (res: Awaited<ReturnType<typeof exportKeyItem>>, text: string | RegExp) => {
                expect(res.status()).toBe(422);
                expect(expect422Messages(await res.text()).join(' ')).toMatch(text);
            };
            await test.step('gate 1: the PUBLIC item → "only private and secret keys are exported."', async () => {
                await expect422(await exportKeyItem(api, exportable.uuid, exportable.keyItems!.publicUuid!, pass12), /only private and secret keys are exported\./);
            });
            await test.step('gate 2: not created as exportable → "was not created or imported as exportable."', async () => {
                await expect422(await exportKeyItem(api, plain.uuid, plain.keyItems!.privateUuid!, pass12), /was not created or imported as exportable\./);
            });
            await test.step('gate 3: disabled → "must be active and enabled to be exported."', async () => {
                await expect422(await exportKeyItem(api, exportable.uuid, exportable.keyItems!.privateUuid!, pass12), /must be active and enabled to be exported\./);
                await enableOwnKey(api, exportable);
            });
            await test.step('gate 0: 11 code points → 422; 12 → 200 octet-stream, encrypted PKCS#8, history EXPORT', async () => {
                const short = await exportKeyItem(api, exportable.uuid, exportable.keyItems!.privateUuid!, 'Qa-passphra');
                expect(short.status()).toBe(422);
                const ok = await exportKeyItem(api, exportable.uuid, exportable.keyItems!.privateUuid!, pass12);
                expect(ok.status(), await ok.text()).toBe(200);
                expect(ok.headers()['content-type'] ?? '').toContain('application/octet-stream');
                expect((await ok.body()).toString('utf8')).toMatch(/^-----BEGIN ENCRYPTED PRIVATE KEY-----/);
                expect(eventsOf(await keyItemHistory(api, exportable.uuid, exportable.keyItems!.privateUuid!), 'EXPORT', 'SUCCESS').length).toBeGreaterThanOrEqual(1);
            });
            await test.step('export/disable → EXPORT_DISABLED, the next export refused', async () => {
                const off = await disableKeyItemExport(api, exportable.uuid, exportable.keyItems!.privateUuid!);
                expect(off.status(), await off.text()).toBeLessThan(300);
                expect(eventsOf(await keyItemHistory(api, exportable.uuid, exportable.keyItems!.privateUuid!), 'EXPORT_DISABLED').length).toBeGreaterThanOrEqual(1);
                const res = await exportKeyItem(api, exportable.uuid, exportable.keyItems!.privateUuid!, pass12);
                expect(res.status()).toBe(422);
            });
        });

    test('API-KEY-23[create-gate]: exportable requested on a v1 profile → the create is refused "Connector … does not support key export." (no key left)',
        meta({ id: 'API-KEY-23', prio: 'P1', issue: 'ilm#431', rule: ['platform-keys-connectors A2 r11 (CryptographicKeyServiceImpl:1287: exportable requested but the connector lacks KEY_EXPORT), ilm#248 (V1 receives no import / export capability)'] }),
        async ({ api }) => {
            test.setTimeout(120_000);
            const v1 = await findCryptoConnector(api, 1);
            test.skip(!v1, 'no connected software cryptography connector of interface v1 is registered on this tier (REG_CRYPTO_CONNECTOR_V1)');
            const token = await createOwnToken(api, v1!, `tokv1x-${Date.now().toString(36)}`, SPEC, { kind: 'SOFT' });
            const profile = await createOwnTokenProfile(api, token, `tpv1x-${Date.now().toString(36)}`, SPEC);
            await enableOwnTokenProfile(api, token, profile);
            const name = regName(`k23v1-${Date.now().toString(36)}`);
            let refused: { status: number; text: string } | undefined;
            try {
                await createOwnKey(api, { token, tokenProfile: profile }, name, SPEC, { family: 'rsa-2048', exportable: true, name });
            } catch (e) {
                const m = /→ (\d{3}) (.*)$/s.exec(String(e));
                refused = m ? { status: Number(m[1]), text: m[2] } : { status: 0, text: String(e) };
            }
            expect(refused, 'the create is refused').toBeTruthy();
            expect(refused!.status).toBe(422);
            expect(refused!.text).toMatch(/does not support key export\./);
            const page = await api.post('/api/v1/keys', { data: { itemsPerPage: 100, pageNumber: 1, filters: [] } });
            expect(((await page.json()).cryptographicKeys ?? []).some((k: Json) => k.name === name), 'no key left').toBe(false);
            void profileUrl;
        });
});
